            <Plus size={15}  data-aime-component-name="Plus"  data-aime-path-name="src/components/life/ProgressPage.tsx"  data-aime-column="13"  data-aime-line="127"  data-insp-path="src/components/life/ProgressPage.tsx:127:13:Plus" />
