import { compressImage } from '@/lib/lifeUtils';
import { Camera, Plus, X } from 'lucide-react';
import { useRef, useState } from 'react';
import { ConfirmModal } from './ConfirmModal';

const MAX_IMAGES = 5;
const MAX_SOURCE_BYTES = 8 * 1024 * 1024;
const MAX_MEAL_BYTES = 1.8 * 1024 * 1024;
const allowed = ['image/jpeg', 'image/png', 'image/webp'];

interface Props {
  label: string;
  images: string[];
  onChange: (images: string[]) => void;
  notify: (text: string) => void;
}

export function MealGallery({ label, images, onChange, notify }: Props) {
  const upload = useRef<HTMLInputElement>(null);
  const [preview, setPreview] = useState<string | null>(null);
  const [pendingRemoval, setPendingRemoval] = useState<number | null>(null);
  const addImages = async (files: FileList | null) => {
    if (!files?.length) return;
    try {
      const incoming = Array.from(files);
      if (images.length + incoming.length > MAX_IMAGES) {
        throw new Error(`每餐最多保存 ${MAX_IMAGES} 张图片`);
      }
      const next = [...images];
      for (const file of incoming) {
        if (!allowed.includes(file.type))
          throw new Error('仅支持 JPG、PNG、WebP 图片');
        if (file.size > MAX_SOURCE_BYTES) throw new Error('单张原图请小于 8MB');
        const compressed = await compressImage(file, 640, 0.66);
        next.push(compressed);
        const bytes = next.reduce((sum, item) => sum + item.length * 0.75, 0);
        if (bytes > MAX_MEAL_BYTES)
          throw new Error('本餐图片容量已满，请删除后再上传');
      }
      onChange(next);
      notify('图片已压缩保存');
    } catch (error) {
      notify((error as Error).message);
    } finally {
      if (upload.current) upload.current.value = '';
    }
  };
  const remove = () => {
    if (pendingRemoval === null) return;
    onChange(images.filter((_, index) => index !== pendingRemoval));
    setPendingRemoval(null);
  };
  return (
    <>
      <div className="meal-gallery" data-aime-component-name="div"  data-aime-path-name="src/components/life/MealGallery.tsx"  data-aime-column="7"  data-aime-line="55"  data-insp-path="src/components/life/MealGallery.tsx:55:7:div" >
        {images.map((image, index) => (
          <div className="meal-image" key={`${image.slice(-18)}-${index}`} data-aime-component-name="div"  data-aime-path-name="src/components/life/MealGallery.tsx"  data-aime-column="11"  data-aime-line="57"  data-insp-path="src/components/life/MealGallery.tsx:57:11:div" >
            <button
              className="meal-preview"
              onClick={() => setPreview(image)}
              aria-label={`查看${label}图片 ${index + 1}`}
             data-aime-component-name="button"  data-aime-path-name="src/components/life/MealGallery.tsx"  data-aime-column="13"  data-aime-line="58"  data-insp-path="src/components/life/MealGallery.tsx:58:13:button" >
              <img src={image} alt={`${label}记录 ${index + 1}`}  data-aime-component-name="img"  data-aime-path-name="src/components/life/MealGallery.tsx"  data-aime-column="15"  data-aime-line="63"  data-insp-path="src/components/life/MealGallery.tsx:63:15:img" />
            </button>
            <button
              className="meal-image-remove"
              onClick={() => setPendingRemoval(index)}
              aria-label={`删除${label}图片 ${index + 1}`}
             data-aime-component-name="button"  data-aime-path-name="src/components/life/MealGallery.tsx"  data-aime-column="13"  data-aime-line="65"  data-insp-path="src/components/life/MealGallery.tsx:65:13:button" >
              <X size={10}  data-aime-component-name="X"  data-aime-path-name="src/components/life/MealGallery.tsx"  data-aime-column="15"  data-aime-line="70"  data-insp-path="src/components/life/MealGallery.tsx:70:15:X" />
            </button>
          </div>
        ))}
        {images.length < MAX_IMAGES && (
          <button
            className="meal-add"
            onClick={() => upload.current?.click()}
            aria-label={`添加${label}图片`}
           data-aime-component-name="button"  data-aime-path-name="src/components/life/MealGallery.tsx"  data-aime-column="11"  data-aime-line="75"  data-insp-path="src/components/life/MealGallery.tsx:75:11:button" >
            {images.length ? <Plus size={15}  data-aime-component-name="Plus"  data-aime-path-name="src/components/life/MealGallery.tsx"  data-aime-column="30"  data-aime-line="80"  data-insp-path="src/components/life/MealGallery.tsx:80:30:Plus" /> : <Camera size={15}  data-aime-component-name="Camera"  data-aime-path-name="src/components/life/MealGallery.tsx"  data-aime-column="51"  data-aime-line="80"  data-insp-path="src/components/life/MealGallery.tsx:80:51:Camera" />}
            {!images.length && <small data-aime-component-name="small" data-aime-path-name="src/components/life/MealGallery.tsx" data-aime-column="32" data-aime-line="81" data-insp-path="src/components/life/MealGallery.tsx:81:32:small">添图</small>}
          </button>
        )}
      </div>
      <input
        ref={upload}
        hidden
        multiple
        type="file"
        accept="image/jpeg,image/png,image/webp"
        onChange={event => addImages(event.target.files)}
       data-aime-component-name="input"  data-aime-path-name="src/components/life/MealGallery.tsx"  data-aime-column="7"  data-aime-line="85"  data-insp-path="src/components/life/MealGallery.tsx:85:7:input" />
      {preview && (
        <div
          className="image-lightbox"
          role="presentation"
          onPointerDown={() => setPreview(null)}
         data-aime-component-name="div"  data-aime-path-name="src/components/life/MealGallery.tsx"  data-aime-column="9"  data-aime-line="94"  data-insp-path="src/components/life/MealGallery.tsx:94:9:div" >
          <button onClick={() => setPreview(null)} aria-label="关闭大图" data-aime-component-name="button"  data-aime-path-name="src/components/life/MealGallery.tsx"  data-aime-column="11"  data-aime-line="99"  data-insp-path="src/components/life/MealGallery.tsx:99:11:button" >
            <X size={20}  data-aime-component-name="X"  data-aime-path-name="src/components/life/MealGallery.tsx"  data-aime-column="13"  data-aime-line="100"  data-insp-path="src/components/life/MealGallery.tsx:100:13:X" />
          </button>
          <img
            src={preview}
            alt={`${label}完整图片`}
            onPointerDown={event => event.stopPropagation()}
           data-aime-component-name="img"  data-aime-path-name="src/components/life/MealGallery.tsx"  data-aime-column="11"  data-aime-line="102"  data-insp-path="src/components/life/MealGallery.tsx:102:11:img" />
        </div>
      )}
      <ConfirmModal
        open={pendingRemoval !== null}
        title="删除饮食图片"
        message="删除后无法恢复，确定移除这张图片吗？"
        confirmLabel="删除"
        onCancel={() => setPendingRemoval(null)}
        onConfirm={remove}
       data-aime-component-name="ConfirmModal"  data-aime-path-name="src/components/life/MealGallery.tsx"  data-aime-column="7"  data-aime-line="109"  data-insp-path="src/components/life/MealGallery.tsx:109:7:ConfirmModal" />
    </>
  );
}
