import type { JournalEntry } from '@/hooks/useLifeStore';
import { Feather, Send, X } from 'lucide-react';
import { useState } from 'react';

export function JournalDrawer({
  entries,
  onEntries,
  notify,
}: {
  entries: JournalEntry[];
  onEntries: (entries: JournalEntry[]) => void;
  notify: (text: string) => void;
}) {
  const preview =
    typeof window !== 'undefined'
      ? new URLSearchParams(window.location.search).get('preview')
      : '';
  const [open, setOpen] = useState(preview === 'journal');
  const [text, setText] = useState('');
  const publish = () => {
    if (!text.trim()) return notify('先写下一点此刻');
    const next = {
      id: Date.now(),
      text: text.trim(),
      createdAt: new Date().toISOString(),
    };
    onEntries([next, ...entries]);
    setText('');
    notify('这一刻已收进时间轴');
  };
  return (
    <>
      <button
        className="journal-handle"
        onClick={() => setOpen(true)}
        aria-label="打开时光日记本"
       data-aime-component-name="button"  data-aime-path-name="src/components/life/JournalDrawer.tsx"  data-aime-column="7"  data-aime-line="33"  data-insp-path="src/components/life/JournalDrawer.tsx:33:7:button" >
        <Feather  data-aime-component-name="Feather" data-aime-path-name="src/components/life/JournalDrawer.tsx" data-aime-column="9" data-aime-line="38" data-insp-path="src/components/life/JournalDrawer.tsx:38:9:Feather"/>
      </button>
      {open && (
        <div className="journal-mask" onPointerDown={() => setOpen(false)} data-aime-component-name="div"  data-aime-path-name="src/components/life/JournalDrawer.tsx"  data-aime-column="9"  data-aime-line="41"  data-insp-path="src/components/life/JournalDrawer.tsx:41:9:div" >
          <aside
            className="journal-drawer"
            onPointerDown={event => event.stopPropagation()}
           data-aime-component-name="aside"  data-aime-path-name="src/components/life/JournalDrawer.tsx"  data-aime-column="11"  data-aime-line="42"  data-insp-path="src/components/life/JournalDrawer.tsx:42:11:aside" >
            <header data-aime-component-name="header" data-aime-path-name="src/components/life/JournalDrawer.tsx" data-aime-column="13" data-aime-line="46" data-insp-path="src/components/life/JournalDrawer.tsx:46:13:header">
              <div data-aime-component-name="div" data-aime-path-name="src/components/life/JournalDrawer.tsx" data-aime-column="15" data-aime-line="47" data-insp-path="src/components/life/JournalDrawer.tsx:47:15:div">
                <span data-aime-component-name="span" data-aime-path-name="src/components/life/JournalDrawer.tsx" data-aime-column="17" data-aime-line="48" data-insp-path="src/components/life/JournalDrawer.tsx:48:17:span">PRIVATE TIMELINE</span>
                <h2 data-aime-component-name="h2" data-aime-path-name="src/components/life/JournalDrawer.tsx" data-aime-column="17" data-aime-line="49" data-insp-path="src/components/life/JournalDrawer.tsx:49:17:h2">时光日记本</h2>
              </div>
              <button onClick={() => setOpen(false)} data-aime-component-name="button"  data-aime-path-name="src/components/life/JournalDrawer.tsx"  data-aime-column="15"  data-aime-line="51"  data-insp-path="src/components/life/JournalDrawer.tsx:51:15:button" >
                <X size={18}  data-aime-component-name="X"  data-aime-path-name="src/components/life/JournalDrawer.tsx"  data-aime-column="17"  data-aime-line="52"  data-insp-path="src/components/life/JournalDrawer.tsx:52:17:X" />
              </button>
            </header>
            <div className="journal-compose" data-aime-component-name="div"  data-aime-path-name="src/components/life/JournalDrawer.tsx"  data-aime-column="13"  data-aime-line="55"  data-insp-path="src/components/life/JournalDrawer.tsx:55:13:div" >
              <textarea
                value={text}
                onChange={event => setText(event.target.value)}
                placeholder="此刻想记下……"
               data-aime-component-name="textarea"  data-aime-path-name="src/components/life/JournalDrawer.tsx"  data-aime-column="15"  data-aime-line="56"  data-insp-path="src/components/life/JournalDrawer.tsx:56:15:textarea" />
              <button className="journal-publish" onClick={publish} data-aime-component-name="button"  data-aime-path-name="src/components/life/JournalDrawer.tsx"  data-aime-column="15"  data-aime-line="61"  data-insp-path="src/components/life/JournalDrawer.tsx:61:15:button" >
                <Send size={15}  data-aime-component-name="Send"  data-aime-path-name="src/components/life/JournalDrawer.tsx"  data-aime-column="17"  data-aime-line="62"  data-insp-path="src/components/life/JournalDrawer.tsx:62:17:Send" />
                <span data-aime-component-name="span" data-aime-path-name="src/components/life/JournalDrawer.tsx" data-aime-column="17" data-aime-line="63" data-insp-path="src/components/life/JournalDrawer.tsx:63:17:span">发布</span>
              </button>
            </div>
            <div className="journal-timeline" data-aime-component-name="div"  data-aime-path-name="src/components/life/JournalDrawer.tsx"  data-aime-column="13"  data-aime-line="66"  data-insp-path="src/components/life/JournalDrawer.tsx:66:13:div" >
              {entries.length ? (
                entries.map(entry => (
                  <article key={entry.id} data-aime-component-name="article"  data-aime-path-name="src/components/life/JournalDrawer.tsx"  data-aime-column="19"  data-aime-line="69"  data-insp-path="src/components/life/JournalDrawer.tsx:69:19:article" >
                    <time data-aime-component-name="time" data-aime-path-name="src/components/life/JournalDrawer.tsx" data-aime-column="21" data-aime-line="70" data-insp-path="src/components/life/JournalDrawer.tsx:70:21:time">
                      {new Intl.DateTimeFormat('zh-CN', {
                        month: '2-digit',
                        day: '2-digit',
                        hour: '2-digit',
                        minute: '2-digit',
                      }).format(new Date(entry.createdAt))}
                    </time>
                    <p data-aime-component-name="p" data-aime-path-name="src/components/life/JournalDrawer.tsx" data-aime-column="21" data-aime-line="78" data-insp-path="src/components/life/JournalDrawer.tsx:78:21:p">{entry.text}</p>
                  </article>
                ))
              ) : (
                <p className="journal-empty" data-aime-component-name="p"  data-aime-path-name="src/components/life/JournalDrawer.tsx"  data-aime-column="17"  data-aime-line="82"  data-insp-path="src/components/life/JournalDrawer.tsx:82:17:p" >时间轴还很安静。</p>
              )}
            </div>
          </aside>
        </div>
      )}
    </>
  );
}
