import type { DayRecord } from '@/hooks/useLifeStore';
import { fromIso, toIso } from '@/lib/lifeUtils';
import {
  CalendarRange,
  Cloud,
  Crown,
  Flame,
  Flower2,
  Hammer,
  X,
} from 'lucide-react';
import { useState } from 'react';

const moods = [
  { name: '平静', tone: 'calm', mouth: '⌣' },
  { name: '开心', tone: 'happy', mouth: '⌣' },
  { name: '疲惫', tone: 'tired', mouth: '﹏' },
  { name: '低落', tone: 'low', mouth: '︵' },
  { name: '焦虑', tone: 'anxious', mouth: '﹏' },
  { name: '暴躁', tone: 'angry', mouth: '⌁' },
] as const;

function Face({ mood, active = false }: { mood: string; active?: boolean }) {
  const item = moods.find(value => value.name === mood) ?? moods[0];
  return (
    <span className={`pixel-face ${item.tone} ${active ? 'is-active' : ''}`} data-aime-component-name="span"  data-aime-path-name="src/components/life/MoodPanel.tsx"  data-aime-column="5"  data-aime-line="26"  data-insp-path="src/components/life/MoodPanel.tsx:26:5:span" >
      <i  data-aime-component-name="i" data-aime-path-name="src/components/life/MoodPanel.tsx" data-aime-column="7" data-aime-line="27" data-insp-path="src/components/life/MoodPanel.tsx:27:7:i"/>
      <i  data-aime-component-name="i" data-aime-path-name="src/components/life/MoodPanel.tsx" data-aime-column="7" data-aime-line="28" data-insp-path="src/components/life/MoodPanel.tsx:28:7:i"/>
      <b data-aime-component-name="b" data-aime-path-name="src/components/life/MoodPanel.tsx" data-aime-column="7" data-aime-line="29" data-insp-path="src/components/life/MoodPanel.tsx:29:7:b">{item.mouth}</b>
      {active && item.tone === 'calm' && <Crown className="mood-crown"  data-aime-component-name="Crown"  data-aime-path-name="src/components/life/MoodPanel.tsx"  data-aime-column="42"  data-aime-line="30"  data-insp-path="src/components/life/MoodPanel.tsx:30:42:Crown" />}
      {active && item.tone === 'happy' && <Flower2 className="mood-flower"  data-aime-component-name="Flower2"  data-aime-path-name="src/components/life/MoodPanel.tsx"  data-aime-column="43"  data-aime-line="31"  data-insp-path="src/components/life/MoodPanel.tsx:31:43:Flower2" />}
      {active && item.tone === 'tired' && (
        <span className="mood-zzz" data-aime-component-name="span"  data-aime-path-name="src/components/life/MoodPanel.tsx"  data-aime-column="9"  data-aime-line="33"  data-insp-path="src/components/life/MoodPanel.tsx:33:9:span" >
          <em data-aime-component-name="em" data-aime-path-name="src/components/life/MoodPanel.tsx" data-aime-column="11" data-aime-line="34" data-insp-path="src/components/life/MoodPanel.tsx:34:11:em">z</em>
          <em data-aime-component-name="em" data-aime-path-name="src/components/life/MoodPanel.tsx" data-aime-column="11" data-aime-line="35" data-insp-path="src/components/life/MoodPanel.tsx:35:11:em">z</em>
          <em data-aime-component-name="em" data-aime-path-name="src/components/life/MoodPanel.tsx" data-aime-column="11" data-aime-line="36" data-insp-path="src/components/life/MoodPanel.tsx:36:11:em">z</em>
        </span>
      )}
      {active && item.tone === 'low' && <Cloud className="mood-cloud"  data-aime-component-name="Cloud"  data-aime-path-name="src/components/life/MoodPanel.tsx"  data-aime-column="41"  data-aime-line="39"  data-insp-path="src/components/life/MoodPanel.tsx:39:41:Cloud" />}
      {active && item.tone === 'anxious' && <Hammer className="mood-hammer"  data-aime-component-name="Hammer"  data-aime-path-name="src/components/life/MoodPanel.tsx"  data-aime-column="45"  data-aime-line="40"  data-insp-path="src/components/life/MoodPanel.tsx:40:45:Hammer" />}
      {active && item.tone === 'angry' && (
        <Flame className="mood-fire" fill="currentColor"  data-aime-component-name="Flame"  data-aime-path-name="src/components/life/MoodPanel.tsx"  data-aime-column="9"  data-aime-line="42"  data-insp-path="src/components/life/MoodPanel.tsx:42:9:Flame" />
      )}
    </span>
  );
}

function MonthOverview({
  date,
  days,
  onClose,
}: { date: string; days: Record<string, DayRecord>; onClose: () => void }) {
  const base = fromIso(date);
  const year = base.getFullYear();
  const month = base.getMonth();
  const total = new Date(year, month + 1, 0).getDate();
  const offset = (new Date(year, month, 1).getDay() + 6) % 7;
  return (
    <div className="modal-mask" onPointerDown={onClose} data-aime-component-name="div"  data-aime-path-name="src/components/life/MoodPanel.tsx"  data-aime-column="5"  data-aime-line="59"  data-insp-path="src/components/life/MoodPanel.tsx:59:5:div" >
      <div
        className="mood-month"
        onPointerDown={event => event.stopPropagation()}
       data-aime-component-name="div"  data-aime-path-name="src/components/life/MoodPanel.tsx"  data-aime-column="7"  data-aime-line="60"  data-insp-path="src/components/life/MoodPanel.tsx:60:7:div" >
        <div className="modal-head" data-aime-component-name="div"  data-aime-path-name="src/components/life/MoodPanel.tsx"  data-aime-column="9"  data-aime-line="64"  data-insp-path="src/components/life/MoodPanel.tsx:64:9:div" >
          <div data-aime-component-name="div" data-aime-path-name="src/components/life/MoodPanel.tsx" data-aime-column="11" data-aime-line="65" data-insp-path="src/components/life/MoodPanel.tsx:65:11:div">
            <span data-aime-component-name="span" data-aime-path-name="src/components/life/MoodPanel.tsx" data-aime-column="13" data-aime-line="66" data-insp-path="src/components/life/MoodPanel.tsx:66:13:span">MOOD CALENDAR</span>
            <h2 data-aime-component-name="h2" data-aime-path-name="src/components/life/MoodPanel.tsx" data-aime-column="13" data-aime-line="67" data-insp-path="src/components/life/MoodPanel.tsx:67:13:h2">
              {year} 年 {month + 1} 月
            </h2>
          </div>
          <button onClick={onClose} data-aime-component-name="button"  data-aime-path-name="src/components/life/MoodPanel.tsx"  data-aime-column="11"  data-aime-line="71"  data-insp-path="src/components/life/MoodPanel.tsx:71:11:button" >
            <X size={18}  data-aime-component-name="X"  data-aime-path-name="src/components/life/MoodPanel.tsx"  data-aime-column="13"  data-aime-line="72"  data-insp-path="src/components/life/MoodPanel.tsx:72:13:X" />
          </button>
        </div>
        <div className="mood-weekdays" data-aime-component-name="div"  data-aime-path-name="src/components/life/MoodPanel.tsx"  data-aime-column="9"  data-aime-line="75"  data-insp-path="src/components/life/MoodPanel.tsx:75:9:div" >
          {['一', '二', '三', '四', '五', '六', '日'].map(item => (
            <span key={item} data-aime-component-name="span"  data-aime-path-name="src/components/life/MoodPanel.tsx"  data-aime-column="13"  data-aime-line="77"  data-insp-path="src/components/life/MoodPanel.tsx:77:13:span" >{item}</span>
          ))}
        </div>
        <div className="mood-calendar-grid" data-aime-component-name="div"  data-aime-path-name="src/components/life/MoodPanel.tsx"  data-aime-column="9"  data-aime-line="80"  data-insp-path="src/components/life/MoodPanel.tsx:80:9:div" >
          {['mon', 'tue', 'wed', 'thu', 'fri', 'sat', 'sun']
            .slice(0, offset)
            .map(dayName => (
              <i key={`blank-${dayName}`}  data-aime-component-name="i"  data-aime-path-name="src/components/life/MoodPanel.tsx"  data-aime-column="15"  data-aime-line="84"  data-insp-path="src/components/life/MoodPanel.tsx:84:15:i" />
            ))}
          {Array.from({ length: total }, (_, index) => {
            const iso = toIso(new Date(year, month, index + 1, 12));
            const mood = days[iso]?.mood;
            return (
              <div key={iso} data-aime-component-name="div"  data-aime-path-name="src/components/life/MoodPanel.tsx"  data-aime-column="15"  data-aime-line="90"  data-insp-path="src/components/life/MoodPanel.tsx:90:15:div" >
                <small data-aime-component-name="small" data-aime-path-name="src/components/life/MoodPanel.tsx" data-aime-column="17" data-aime-line="91" data-insp-path="src/components/life/MoodPanel.tsx:91:17:small">{index + 1}</small>
                {mood ? <Face mood={mood}  data-aime-component-name="Face"  data-aime-path-name="src/components/life/MoodPanel.tsx"  data-aime-column="25"  data-aime-line="92"  data-insp-path="src/components/life/MoodPanel.tsx:92:25:Face" /> : <span className="empty-face"  data-aime-component-name="span"  data-aime-path-name="src/components/life/MoodPanel.tsx"  data-aime-column="48"  data-aime-line="92"  data-insp-path="src/components/life/MoodPanel.tsx:92:48:span" />}
              </div>
            );
          })}
        </div>
      </div>
    </div>
  );
}

export function MoodPanel({
  date,
  day,
  days,
  onDay,
}: {
  date: string;
  day: DayRecord;
  days: Record<string, DayRecord>;
  onDay: (day: DayRecord) => void;
}) {
  const preview =
    typeof window !== 'undefined'
      ? new URLSearchParams(window.location.search).get('preview')
      : '';
  const [monthOpen, setMonthOpen] = useState(preview === 'month');
  const shownMood = preview === 'mood' && !day.mood ? '焦虑' : day.mood;
  return (
    <section className="life-section mood-section" data-aime-component-name="section"  data-aime-path-name="src/components/life/MoodPanel.tsx"  data-aime-column="5"  data-aime-line="120"  data-insp-path="src/components/life/MoodPanel.tsx:120:5:section" >
      <div className="section-heading" data-aime-component-name="div"  data-aime-path-name="src/components/life/MoodPanel.tsx"  data-aime-column="7"  data-aime-line="121"  data-insp-path="src/components/life/MoodPanel.tsx:121:7:div" >
        <h2 data-aime-component-name="h2" data-aime-path-name="src/components/life/MoodPanel.tsx" data-aime-column="9" data-aime-line="122" data-insp-path="src/components/life/MoodPanel.tsx:122:9:h2">这一天感觉怎样？</h2>
        <button className="outline-action" onClick={() => setMonthOpen(true)} data-aime-component-name="button"  data-aime-path-name="src/components/life/MoodPanel.tsx"  data-aime-column="9"  data-aime-line="123"  data-insp-path="src/components/life/MoodPanel.tsx:123:9:button" >
          <CalendarRange size={14}  data-aime-component-name="CalendarRange"  data-aime-path-name="src/components/life/MoodPanel.tsx"  data-aime-column="11"  data-aime-line="124"  data-insp-path="src/components/life/MoodPanel.tsx:124:11:CalendarRange" />
          月度概览
        </button>
      </div>
      <div className="mood-row" data-aime-component-name="div"  data-aime-path-name="src/components/life/MoodPanel.tsx"  data-aime-column="7"  data-aime-line="128"  data-insp-path="src/components/life/MoodPanel.tsx:128:7:div" >
        {moods.map(item => {
          const selected = shownMood === item.name;
          return (
            <button
              className={`pixel-mood ${selected ? 'selected' : ''}`}
              key={item.name}
              onClick={() => onDay({ ...day, mood: item.name })}
             data-aime-component-name="button"  data-aime-path-name="src/components/life/MoodPanel.tsx"  data-aime-column="13"  data-aime-line="132"  data-insp-path="src/components/life/MoodPanel.tsx:132:13:button" >
              <Face mood={item.name} active={selected}  data-aime-component-name="Face"  data-aime-path-name="src/components/life/MoodPanel.tsx"  data-aime-column="15"  data-aime-line="137"  data-insp-path="src/components/life/MoodPanel.tsx:137:15:Face" />
              <small data-aime-component-name="small" data-aime-path-name="src/components/life/MoodPanel.tsx" data-aime-column="15" data-aime-line="138" data-insp-path="src/components/life/MoodPanel.tsx:138:15:small">{item.name}</small>
            </button>
          );
        })}
      </div>
      {shownMood && (
        <label className="mood-factor" data-aime-component-name="label"  data-aime-path-name="src/components/life/MoodPanel.tsx"  data-aime-column="9"  data-aime-line="144"  data-insp-path="src/components/life/MoodPanel.tsx:144:9:label" >
          <span data-aime-component-name="span" data-aime-path-name="src/components/life/MoodPanel.tsx" data-aime-column="11" data-aime-line="145" data-insp-path="src/components/life/MoodPanel.tsx:145:11:span">今天主要被什么影响？</span>
          <input
            value={day.moodFactor ?? ''}
            onChange={event =>
              onDay({ ...day, moodFactor: event.target.value })
            }
            placeholder="写下一件事或一个人"
           data-aime-component-name="input"  data-aime-path-name="src/components/life/MoodPanel.tsx"  data-aime-column="11"  data-aime-line="146"  data-insp-path="src/components/life/MoodPanel.tsx:146:11:input" />
        </label>
      )}
      {monthOpen && (
        <MonthOverview
          date={date}
          days={days}
          onClose={() => setMonthOpen(false)}
         data-aime-component-name="MonthOverview"  data-aime-path-name="src/components/life/MoodPanel.tsx"  data-aime-column="9"  data-aime-line="156"  data-insp-path="src/components/life/MoodPanel.tsx:156:9:MonthOverview" />
      )}
    </section>
  );
}
