import type {
  LifeState,
  MoneyTransaction,
  MonthlyMoney,
  PendingExpense,
} from '@/hooks/useLifeStore';
import {
  createSavingsIsland,
  deleteSavingsIsland,
  mergeMonthlyMoneySummary,
  renameSavingsIsland,
} from '@/lib/lifeRules';
import { safeCalculate } from '@/lib/lifeUtils';
import { Plus } from 'lucide-react';
import { useState } from 'react';
import {
  Bar,
  BarChart,
  CartesianGrid,
  ResponsiveContainer,
  Tooltip,
  XAxis,
  YAxis,
} from 'recharts';
import { MoneyCalendar } from './MoneyCalendar';
import { MonthlyMoneyEditor } from './MonthlyMoneyEditor';
import { PendingExpenses } from './PendingExpenses';
import { SavingsIsland } from './SavingsIsland';

type Saving = LifeState['savings'][number];
interface Props {
  savings: Saving[];
  transactions: MoneyTransaction[];
  monthlyMoney: MonthlyMoney[];
  pendingExpenses: PendingExpense[];
  onSavings: (items: Saving[]) => void;
  onTransactions: (items: MoneyTransaction[]) => void;
  onMonthlyMoney: (items: MonthlyMoney[]) => void;
  onPendingExpenses: (items: PendingExpense[]) => void;
  notify: (text: string) => void;
}

export function MoneyPage({
  savings,
  transactions,
  monthlyMoney,
  pendingExpenses,
  onSavings,
  onTransactions,
  onMonthlyMoney,
  onPendingExpenses,
  notify,
}: Props) {
  const [editingName, setEditingName] = useState<string | null>(null);
  const [editingSavings, setEditingSavings] = useState(false);
  const commitSaving = (item: Saving, expression: string) => {
    try {
      const value = safeCalculate(expression);
      onSavings(
        savings.map(saving =>
          saving.id === item.id
            ? {
                ...saving,
                expression,
                value,
                updatedAt: new Date().toISOString(),
              }
            : saving,
        ),
      );
      return true;
    } catch (error) {
      notify((error as Error).message);
      return false;
    }
  };
  const addIsland = () => {
    const id = `island-${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 7)}`;
    onSavings([...savings, createSavingsIsland(id, savings.length + 1)]);
    setEditingSavings(true);
    setEditingName(id);
  };
  const total = savings.reduce((sum, item) => sum + item.value, 0);
  const visibleChart = mergeMonthlyMoneySummary(transactions, monthlyMoney).map(
    item => ({
      label: `${Number(item.month.slice(5))}月`,
      income: item.income / 100,
      expense: item.expense / 100,
    }),
  );
  return (
    <>
      <section className="savings-card narrow" data-aime-component-name="section"  data-aime-path-name="src/components/life/MoneyPage.tsx"  data-aime-column="7"  data-aime-line="93"  data-insp-path="src/components/life/MoneyPage.tsx:93:7:section" >
        <div className="savings-top" data-aime-component-name="div"  data-aime-path-name="src/components/life/MoneyPage.tsx"  data-aime-column="9"  data-aime-line="94"  data-insp-path="src/components/life/MoneyPage.tsx:94:9:div" >
          <div data-aime-component-name="div" data-aime-path-name="src/components/life/MoneyPage.tsx" data-aime-column="11" data-aime-line="95" data-insp-path="src/components/life/MoneyPage.tsx:95:11:div">
            <span className="overline" data-aime-component-name="span"  data-aime-path-name="src/components/life/MoneyPage.tsx"  data-aime-column="13"  data-aime-line="96"  data-insp-path="src/components/life/MoneyPage.tsx:96:13:span" >PLATFORM SAVINGS</span>
            <h2 data-aime-component-name="h2" data-aime-path-name="src/components/life/MoneyPage.tsx" data-aime-column="13" data-aime-line="97" data-insp-path="src/components/life/MoneyPage.tsx:97:13:h2">平台储蓄</h2>
          </div>
          <button
            type="button"
            className="savings-edit-toggle"
            aria-pressed={editingSavings}
            onClick={() => {
              setEditingSavings(active => !active);
              setEditingName(null);
            }}
           data-aime-component-name="button"  data-aime-path-name="src/components/life/MoneyPage.tsx"  data-aime-column="11"  data-aime-line="99"  data-insp-path="src/components/life/MoneyPage.tsx:99:11:button" >
            {editingSavings ? '完成' : '编辑'}
          </button>
        </div>
        <div className="island-map" data-aime-component-name="div"  data-aime-path-name="src/components/life/MoneyPage.tsx"  data-aime-column="9"  data-aime-line="111"  data-insp-path="src/components/life/MoneyPage.tsx:111:9:div" >
          <div className="wave wave-one"  data-aime-component-name="div"  data-aime-path-name="src/components/life/MoneyPage.tsx"  data-aime-column="11"  data-aime-line="112"  data-insp-path="src/components/life/MoneyPage.tsx:112:11:div" />
          <div className="wave wave-two"  data-aime-component-name="div"  data-aime-path-name="src/components/life/MoneyPage.tsx"  data-aime-column="11"  data-aime-line="113"  data-insp-path="src/components/life/MoneyPage.tsx:113:11:div" />
          <div className="island-list" data-aime-component-name="div"  data-aime-path-name="src/components/life/MoneyPage.tsx"  data-aime-column="11"  data-aime-line="114"  data-insp-path="src/components/life/MoneyPage.tsx:114:11:div" >
            {savings.map(item => (
              <SavingsIsland
                item={item}
                key={item.id}
                editMode={editingSavings}
                editingName={editingName === item.id}
                onEditingName={active =>
                  setEditingName(active ? item.id : null)
                }
                onName={displayName =>
                  onSavings(renameSavingsIsland(savings, item.id, displayName))
                }
                onAmount={expression => commitSaving(item, expression)}
                onDelete={() =>
                  onSavings(deleteSavingsIsland(savings, item.id))
                }
               data-aime-component-name="SavingsIsland"  data-aime-path-name="src/components/life/MoneyPage.tsx"  data-aime-column="15"  data-aime-line="116"  data-insp-path="src/components/life/MoneyPage.tsx:116:15:SavingsIsland" />
            ))}
            {!savings.length && !editingSavings && (
              <button className="add-island" onClick={addIsland} data-aime-component-name="button"  data-aime-path-name="src/components/life/MoneyPage.tsx"  data-aime-column="15"  data-aime-line="134"  data-insp-path="src/components/life/MoneyPage.tsx:134:15:button" >
                <Plus size={13}  data-aime-component-name="Plus"  data-aime-path-name="src/components/life/MoneyPage.tsx"  data-aime-column="17"  data-aime-line="135"  data-insp-path="src/components/life/MoneyPage.tsx:135:17:Plus" />
                添加第一个储蓄岛
              </button>
            )}
            {editingSavings && (
              <button className="add-island" onClick={addIsland} data-aime-component-name="button"  data-aime-path-name="src/components/life/MoneyPage.tsx"  data-aime-column="15"  data-aime-line="140"  data-insp-path="src/components/life/MoneyPage.tsx:140:15:button" >
                <Plus size={13}  data-aime-component-name="Plus"  data-aime-path-name="src/components/life/MoneyPage.tsx"  data-aime-column="17"  data-aime-line="141"  data-insp-path="src/components/life/MoneyPage.tsx:141:17:Plus" />
                添加岛屿
              </button>
            )}
          </div>
        </div>
        <p className="savings-total" data-aime-component-name="p"  data-aime-path-name="src/components/life/MoneyPage.tsx"  data-aime-column="9"  data-aime-line="147"  data-insp-path="src/components/life/MoneyPage.tsx:147:9:p" >
          总储蓄 <strong data-aime-component-name="strong" data-aime-path-name="src/components/life/MoneyPage.tsx" data-aime-column="15" data-aime-line="148" data-insp-path="src/components/life/MoneyPage.tsx:148:15:strong">{total.toLocaleString()}</strong> 元
        </p>
      </section>

      <MoneyCalendar
        transactions={transactions}
        onChange={onTransactions}
        notify={notify}
       data-aime-component-name="MoneyCalendar"  data-aime-path-name="src/components/life/MoneyPage.tsx"  data-aime-column="7"  data-aime-line="152"  data-insp-path="src/components/life/MoneyPage.tsx:152:7:MoneyCalendar" />

      <section className="life-section money-chart-section" data-aime-component-name="section"  data-aime-path-name="src/components/life/MoneyPage.tsx"  data-aime-column="7"  data-aime-line="158"  data-insp-path="src/components/life/MoneyPage.tsx:158:7:section" >
        <div className="section-heading" data-aime-component-name="div"  data-aime-path-name="src/components/life/MoneyPage.tsx"  data-aime-column="9"  data-aime-line="159"  data-insp-path="src/components/life/MoneyPage.tsx:159:9:div" >
          <div data-aime-component-name="div" data-aime-path-name="src/components/life/MoneyPage.tsx" data-aime-column="11" data-aime-line="160" data-insp-path="src/components/life/MoneyPage.tsx:160:11:div">
            <div className="money-title-row" data-aime-component-name="div"  data-aime-path-name="src/components/life/MoneyPage.tsx"  data-aime-column="13"  data-aime-line="161"  data-insp-path="src/components/life/MoneyPage.tsx:161:13:div" >
              <h2 data-aime-component-name="h2" data-aime-path-name="src/components/life/MoneyPage.tsx" data-aime-column="15" data-aime-line="162" data-insp-path="src/components/life/MoneyPage.tsx:162:15:h2">月度收支</h2>
              <MonthlyMoneyEditor
                items={monthlyMoney}
                onChange={onMonthlyMoney}
                notify={notify}
               data-aime-component-name="MonthlyMoneyEditor"  data-aime-path-name="src/components/life/MoneyPage.tsx"  data-aime-column="15"  data-aime-line="163"  data-insp-path="src/components/life/MoneyPage.tsx:163:15:MonthlyMoneyEditor" />
            </div>
            <p data-aime-component-name="p" data-aime-path-name="src/components/life/MoneyPage.tsx" data-aime-column="13" data-aime-line="169" data-insp-path="src/components/life/MoneyPage.tsx:169:13:p">日明细整月优先 · 单位：元</p>
          </div>
          <span className="bar-legend" data-aime-component-name="span"  data-aime-path-name="src/components/life/MoneyPage.tsx"  data-aime-column="11"  data-aime-line="171"  data-insp-path="src/components/life/MoneyPage.tsx:171:11:span" >
            <i  data-aime-component-name="i" data-aime-path-name="src/components/life/MoneyPage.tsx" data-aime-column="13" data-aime-line="172" data-insp-path="src/components/life/MoneyPage.tsx:172:13:i"/>
            收入
            <i  data-aime-component-name="i" data-aime-path-name="src/components/life/MoneyPage.tsx" data-aime-column="13" data-aime-line="174" data-insp-path="src/components/life/MoneyPage.tsx:174:13:i"/>
            支出
          </span>
        </div>
        <div className="money-chart" data-aime-component-name="div"  data-aime-path-name="src/components/life/MoneyPage.tsx"  data-aime-column="9"  data-aime-line="178"  data-insp-path="src/components/life/MoneyPage.tsx:178:9:div" >
          <ResponsiveContainer width="100%" height={210} data-aime-component-name="ResponsiveContainer"  data-aime-path-name="src/components/life/MoneyPage.tsx"  data-aime-column="11"  data-aime-line="179"  data-insp-path="src/components/life/MoneyPage.tsx:179:11:ResponsiveContainer" >
            <BarChart
              data={visibleChart}
              barGap={4}
              margin={{ top: 10, right: 4, left: -12, bottom: 0 }}
             data-aime-component-name="BarChart"  data-aime-path-name="src/components/life/MoneyPage.tsx"  data-aime-column="13"  data-aime-line="180"  data-insp-path="src/components/life/MoneyPage.tsx:180:13:BarChart" >
              <CartesianGrid stroke="#ece9e3" vertical={false}  data-aime-component-name="CartesianGrid"  data-aime-path-name="src/components/life/MoneyPage.tsx"  data-aime-column="15"  data-aime-line="185"  data-insp-path="src/components/life/MoneyPage.tsx:185:15:CartesianGrid" />
              <XAxis
                dataKey="label"
                axisLine={false}
                tickLine={false}
                tick={{ fill: '#85827d', fontSize: 10 }}
               data-aime-component-name="XAxis"  data-aime-path-name="src/components/life/MoneyPage.tsx"  data-aime-column="15"  data-aime-line="186"  data-insp-path="src/components/life/MoneyPage.tsx:186:15:XAxis" />
              <YAxis
                axisLine={false}
                tickLine={false}
                tick={{ fill: '#aaa59d', fontSize: 9 }}
               data-aime-component-name="YAxis"  data-aime-path-name="src/components/life/MoneyPage.tsx"  data-aime-column="15"  data-aime-line="192"  data-insp-path="src/components/life/MoneyPage.tsx:192:15:YAxis" />
              <Tooltip
                cursor={{ fill: '#f6f3ed' }}
                formatter={value => `¥${Number(value).toFixed(2)}`}
                contentStyle={{
                  border: '1px solid #ddd8cf',
                  borderRadius: 12,
                  fontSize: 11,
                }}
               data-aime-component-name="Tooltip"  data-aime-path-name="src/components/life/MoneyPage.tsx"  data-aime-column="15"  data-aime-line="197"  data-insp-path="src/components/life/MoneyPage.tsx:197:15:Tooltip" />
              <Bar
                dataKey="income"
                name="收入"
                fill="#91aaa0"
                radius={[5, 5, 2, 2]}
                maxBarSize={16}
               data-aime-component-name="Bar"  data-aime-path-name="src/components/life/MoneyPage.tsx"  data-aime-column="15"  data-aime-line="206"  data-insp-path="src/components/life/MoneyPage.tsx:206:15:Bar" />
              <Bar
                dataKey="expense"
                name="支出"
                fill="#d4a99e"
                radius={[5, 5, 2, 2]}
                maxBarSize={16}
               data-aime-component-name="Bar"  data-aime-path-name="src/components/life/MoneyPage.tsx"  data-aime-column="15"  data-aime-line="213"  data-insp-path="src/components/life/MoneyPage.tsx:213:15:Bar" />
            </BarChart>
          </ResponsiveContainer>
        </div>
      </section>

      <PendingExpenses
        items={pendingExpenses}
        onChange={onPendingExpenses}
        notify={notify}
       data-aime-component-name="PendingExpenses"  data-aime-path-name="src/components/life/MoneyPage.tsx"  data-aime-column="7"  data-aime-line="225"  data-insp-path="src/components/life/MoneyPage.tsx:225:7:PendingExpenses" />
    </>
  );
}
