import type { ConfigItem, ProgressRecord } from '@/hooks/useLifeStore';
import { Check } from 'lucide-react';
import { type PointerEvent, useEffect, useState } from 'react';
import { LifeIcon } from './LifeIcon';

interface Props {
  items: ConfigItem[];
  records: Record<string, ProgressRecord>;
  onChange: (records: Record<string, ProgressRecord>) => void;
}

interface CardProps {
  item: ConfigItem;
  record: ProgressRecord;
  onPatch: (value: Partial<ProgressRecord>) => void;
}

const stopPointer = (event: PointerEvent<HTMLElement>) =>
  event.stopPropagation();

function ProgressCard({ item, record, onPatch }: CardProps) {
  const [planned, setPlanned] = useState(String(record.planned));
  useEffect(() => setPlanned(String(record.planned)), [record.planned]);

  const savePlanned = () => {
    const value = Math.max(0, Math.min(9999, Number(planned) || 0));
    setPlanned(String(value));
    if (value !== record.planned) onPatch({ planned: value });
  };
  const toggle = () => onPatch({ completed: !record.completed });

  return (
    <article
      className={`progress-check-card ${item.tone ?? 'sage'} ${record.completed ? 'completed' : ''}`}
     data-aime-component-name="article"  data-aime-path-name="src/components/life/ProgressCheckins.tsx"  data-aime-column="5"  data-aime-line="33"  data-insp-path="src/components/life/ProgressCheckins.tsx:33:5:article" >
      <button
        type="button"
        className="progress-card-main"
        aria-label={`${record.completed ? '取消' : '完成'}${item.name}`}
        aria-pressed={record.completed}
        onClick={toggle}
       data-aime-component-name="button"  data-aime-path-name="src/components/life/ProgressCheckins.tsx"  data-aime-column="7"  data-aime-line="36"  data-insp-path="src/components/life/ProgressCheckins.tsx:36:7:button" >
        <span className="progress-card-icon" data-aime-component-name="span"  data-aime-path-name="src/components/life/ProgressCheckins.tsx"  data-aime-column="9"  data-aime-line="43"  data-insp-path="src/components/life/ProgressCheckins.tsx:43:9:span" >
          <LifeIcon id={item.iconId}  data-aime-component-name="LifeIcon"  data-aime-path-name="src/components/life/ProgressCheckins.tsx"  data-aime-column="11"  data-aime-line="44"  data-insp-path="src/components/life/ProgressCheckins.tsx:44:11:LifeIcon" />
        </span>
        <span className="progress-card-check" data-aime-component-name="span"  data-aime-path-name="src/components/life/ProgressCheckins.tsx"  data-aime-column="9"  data-aime-line="46"  data-insp-path="src/components/life/ProgressCheckins.tsx:46:9:span" >
          <Check size={13}  data-aime-component-name="Check"  data-aime-path-name="src/components/life/ProgressCheckins.tsx"  data-aime-column="11"  data-aime-line="47"  data-insp-path="src/components/life/ProgressCheckins.tsx:47:11:Check" />
        </span>
        <b data-aime-component-name="b" data-aime-path-name="src/components/life/ProgressCheckins.tsx" data-aime-column="9" data-aime-line="49" data-insp-path="src/components/life/ProgressCheckins.tsx:49:9:b">{item.name}</b>
      </button>
      <label
        onPointerDown={stopPointer}
        onClick={event => event.stopPropagation()}
       data-aime-component-name="label"  data-aime-path-name="src/components/life/ProgressCheckins.tsx"  data-aime-column="7"  data-aime-line="51"  data-insp-path="src/components/life/ProgressCheckins.tsx:51:7:label" >
        <input
          aria-label={`${item.name}计划值`}
          inputMode="numeric"
          pattern="[0-9]*"
          type="text"
          value={planned}
          onFocus={event => event.currentTarget.select()}
          onClick={event => {
            event.stopPropagation();
            event.currentTarget.select();
          }}
          onPointerDown={event => event.stopPropagation()}
          onKeyDown={event => {
            event.stopPropagation();
            if (event.key === 'Enter') event.currentTarget.blur();
          }}
          onChange={event =>
            setPlanned(event.target.value.replace(/\D/g, '').slice(0, 4))
          }
          onBlur={savePlanned}
         data-aime-component-name="input"  data-aime-path-name="src/components/life/ProgressCheckins.tsx"  data-aime-column="9"  data-aime-line="55"  data-insp-path="src/components/life/ProgressCheckins.tsx:55:9:input" />
        <span data-aime-component-name="span" data-aime-path-name="src/components/life/ProgressCheckins.tsx" data-aime-column="9" data-aime-line="76" data-insp-path="src/components/life/ProgressCheckins.tsx:76:9:span">{item.unit}</span>
      </label>
    </article>
  );
}

const DAILY_ENGLISH_IDS = new Set(['progress-listening', 'progress-speaking']);

export function ProgressCheckins({ items, records, onChange }: Props) {
  const active = items.filter(item => !item.archivedAt);
  const englishItems = active.filter(item => DAILY_ENGLISH_IDS.has(item.id));
  const otherItems = active.filter(item => !DAILY_ENGLISH_IDS.has(item.id));
  const recordFor = (id: string) =>
    records[id] ?? { planned: 0, completed: false };
  const patch = (id: string, value: Partial<ProgressRecord>) =>
    onChange({ ...records, [id]: { ...recordFor(id), ...value } });
  const renderCard = (item: ConfigItem) => (
    <ProgressCard
      key={item.id}
      item={item}
      record={recordFor(item.id)}
      onPatch={value => patch(item.id, value)}
     data-aime-component-name="ProgressCard"  data-aime-path-name="src/components/life/ProgressCheckins.tsx"  data-aime-column="5"  data-aime-line="93"  data-insp-path="src/components/life/ProgressCheckins.tsx:93:5:ProgressCard" />
  );

  return (
    <section className="life-section progress-checkin-section" data-aime-component-name="section"  data-aime-path-name="src/components/life/ProgressCheckins.tsx"  data-aime-column="5"  data-aime-line="102"  data-insp-path="src/components/life/ProgressCheckins.tsx:102:5:section" >
      {englishItems.length > 0 && (
        <div className="progress-group" data-aime-component-name="div"  data-aime-path-name="src/components/life/ProgressCheckins.tsx"  data-aime-column="9"  data-aime-line="104"  data-insp-path="src/components/life/ProgressCheckins.tsx:104:9:div" >
          <h2 className="progress-module-title" data-aime-component-name="h2"  data-aime-path-name="src/components/life/ProgressCheckins.tsx"  data-aime-column="11"  data-aime-line="105"  data-insp-path="src/components/life/ProgressCheckins.tsx:105:11:h2" >每日英语</h2>
          <div className="progress-checkin-grid" data-aime-component-name="div"  data-aime-path-name="src/components/life/ProgressCheckins.tsx"  data-aime-column="11"  data-aime-line="106"  data-insp-path="src/components/life/ProgressCheckins.tsx:106:11:div" >
            {englishItems.map(renderCard)}
          </div>
        </div>
      )}
      {otherItems.length > 0 && (
        <div className="progress-checkin-grid progress-other-items" data-aime-component-name="div"  data-aime-path-name="src/components/life/ProgressCheckins.tsx"  data-aime-column="9"  data-aime-line="112"  data-insp-path="src/components/life/ProgressCheckins.tsx:112:9:div" >
          {otherItems.map(renderCard)}
        </div>
      )}
    </section>
  );
}
