import { AlertTriangle } from 'lucide-react';
import { useEffect } from 'react';

interface Props {
  open: boolean;
  title?: string;
  message: string;
  confirmLabel?: string;
  onCancel: () => void;
  onConfirm: () => void;
}

export function ConfirmModal({
  open,
  title = '确认操作',
  message,
  confirmLabel = '确定',
  onCancel,
  onConfirm,
}: Props) {
  useEffect(() => {
    if (!open) return;
    const onKeyDown = (event: KeyboardEvent) => {
      if (event.key === 'Escape') onCancel();
    };
    window.addEventListener('keydown', onKeyDown);
    return () => window.removeEventListener('keydown', onKeyDown);
  }, [open, onCancel]);

  if (!open) return null;

  return (
    <div className="confirm-modal-mask" onPointerDown={onCancel} data-aime-component-name="div"  data-aime-path-name="src/components/life/ConfirmModal.tsx"  data-aime-column="5"  data-aime-line="33"  data-insp-path="src/components/life/ConfirmModal.tsx:33:5:div" >
      <section
        className="confirm-modal"
        role="alertdialog"
        aria-modal="true"
        aria-labelledby="confirm-modal-title"
        aria-describedby="confirm-modal-message"
        onPointerDown={event => event.stopPropagation()}
       data-aime-component-name="section"  data-aime-path-name="src/components/life/ConfirmModal.tsx"  data-aime-column="7"  data-aime-line="34"  data-insp-path="src/components/life/ConfirmModal.tsx:34:7:section" >
        <span className="confirm-modal-icon" aria-hidden="true" data-aime-component-name="span"  data-aime-path-name="src/components/life/ConfirmModal.tsx"  data-aime-column="9"  data-aime-line="42"  data-insp-path="src/components/life/ConfirmModal.tsx:42:9:span" >
          <AlertTriangle size={18}  data-aime-component-name="AlertTriangle"  data-aime-path-name="src/components/life/ConfirmModal.tsx"  data-aime-column="11"  data-aime-line="43"  data-insp-path="src/components/life/ConfirmModal.tsx:43:11:AlertTriangle" />
        </span>
        <h2 id="confirm-modal-title" data-aime-component-name="h2"  data-aime-path-name="src/components/life/ConfirmModal.tsx"  data-aime-column="9"  data-aime-line="45"  data-insp-path="src/components/life/ConfirmModal.tsx:45:9:h2" >{title}</h2>
        <p id="confirm-modal-message" data-aime-component-name="p"  data-aime-path-name="src/components/life/ConfirmModal.tsx"  data-aime-column="9"  data-aime-line="46"  data-insp-path="src/components/life/ConfirmModal.tsx:46:9:p" >{message}</p>
        <div className="confirm-modal-actions" data-aime-component-name="div"  data-aime-path-name="src/components/life/ConfirmModal.tsx"  data-aime-column="9"  data-aime-line="47"  data-insp-path="src/components/life/ConfirmModal.tsx:47:9:div" >
          <button type="button" onClick={onCancel} data-aime-component-name="button"  data-aime-path-name="src/components/life/ConfirmModal.tsx"  data-aime-column="11"  data-aime-line="48"  data-insp-path="src/components/life/ConfirmModal.tsx:48:11:button" >
            取消
          </button>
          <button type="button" className="danger" onClick={onConfirm} autoFocus data-aime-component-name="button"  data-aime-path-name="src/components/life/ConfirmModal.tsx"  data-aime-column="11"  data-aime-line="51"  data-insp-path="src/components/life/ConfirmModal.tsx:51:11:button" >
            {confirmLabel}
          </button>
        </div>
      </section>
    </div>
  );
}
