import type { MoneyTransaction } from '@/hooks/useLifeStore';
import {
  calendarCells,
  createMoneyTransaction,
  formatCents,
  summarizeTransactions,
} from '@/lib/lifeRules';
import { Check, ChevronLeft, ChevronRight, Trash2 } from 'lucide-react';
import { useMemo, useState } from 'react';
import { ConfirmModal } from './ConfirmModal';

interface Props {
  transactions: MoneyTransaction[];
  onChange: (items: MoneyTransaction[]) => void;
  notify: (text: string) => void;
}

const monthLabel = (month: string) => {
  const [year, value] = month.split('-');
  return `${year} 年 ${Number(value)} 月`;
};

export function MoneyCalendar({ transactions, onChange, notify }: Props) {
  const [month, setMonth] = useState(() =>
    new Date().toISOString().slice(0, 7),
  );
  const [selected, setSelected] = useState(() =>
    new Date().toISOString().slice(0, 10),
  );
  const [kind, setKind] = useState<'income' | 'expense'>('expense');
  const [amount, setAmount] = useState('');
  const [detail, setDetail] = useState('');
  const [pendingRemoval, setPendingRemoval] = useState<number | null>(null);
  const byDay = useMemo(() => {
    const map = new Map<string, MoneyTransaction[]>();
    for (const item of transactions)
      map.set(item.date, [...(map.get(item.date) ?? []), item]);
    return map;
  }, [transactions]);
  const [year, monthNumber] = month.split('-').map(Number);
  const cells = calendarCells(month);
  const move = (offset: number) => {
    const next = new Date(year, monthNumber - 1 + offset, 1);
    const value = `${next.getFullYear()}-${String(next.getMonth() + 1).padStart(2, '0')}`;
    setMonth(value);
    setSelected(`${value}-01`);
  };
  const selectedItems = byDay.get(selected) ?? [];
  const remove = () => {
    if (pendingRemoval === null) return;
    onChange(transactions.filter(item => item.id !== pendingRemoval));
    setPendingRemoval(null);
  };
  const submit = () => {
    try {
      const transaction = createMoneyTransaction(
        selected,
        kind,
        amount,
        detail,
      );
      onChange([transaction, ...transactions]);
      setAmount('');
      setDetail('');
      notify(`已记入 ${selected.slice(5).replace('-', ' 月 ')} 日`);
    } catch (error) {
      notify((error as Error).message);
    }
  };

  return (
    <section className="money-calendar-section" data-aime-component-name="section"  data-aime-path-name="src/components/life/MoneyCalendar.tsx"  data-aime-column="5"  data-aime-line="72"  data-insp-path="src/components/life/MoneyCalendar.tsx:72:5:section" >
      <div className="section-heading money-daily-heading" data-aime-component-name="div"  data-aime-path-name="src/components/life/MoneyCalendar.tsx"  data-aime-column="7"  data-aime-line="73"  data-insp-path="src/components/life/MoneyCalendar.tsx:73:7:div" >
        <div data-aime-component-name="div" data-aime-path-name="src/components/life/MoneyCalendar.tsx" data-aime-column="9" data-aime-line="74" data-insp-path="src/components/life/MoneyCalendar.tsx:74:9:div">
          <span className="overline" data-aime-component-name="span"  data-aime-path-name="src/components/life/MoneyCalendar.tsx"  data-aime-column="11"  data-aime-line="75"  data-insp-path="src/components/life/MoneyCalendar.tsx:75:11:span" >DAILY MONEY</span>
          <h2 data-aime-component-name="h2" data-aime-path-name="src/components/life/MoneyCalendar.tsx" data-aime-column="11" data-aime-line="76" data-insp-path="src/components/life/MoneyCalendar.tsx:76:11:h2">每日记账</h2>
        </div>
      </div>
      <div className="calendar-month-head" data-aime-component-name="div"  data-aime-path-name="src/components/life/MoneyCalendar.tsx"  data-aime-column="7"  data-aime-line="79"  data-insp-path="src/components/life/MoneyCalendar.tsx:79:7:div" >
        <button onClick={() => move(-1)} aria-label="上个月" data-aime-component-name="button"  data-aime-path-name="src/components/life/MoneyCalendar.tsx"  data-aime-column="9"  data-aime-line="80"  data-insp-path="src/components/life/MoneyCalendar.tsx:80:9:button" >
          <ChevronLeft size={17}  data-aime-component-name="ChevronLeft"  data-aime-path-name="src/components/life/MoneyCalendar.tsx"  data-aime-column="11"  data-aime-line="81"  data-insp-path="src/components/life/MoneyCalendar.tsx:81:11:ChevronLeft" />
        </button>
        <h3 data-aime-component-name="h3" data-aime-path-name="src/components/life/MoneyCalendar.tsx" data-aime-column="9" data-aime-line="83" data-insp-path="src/components/life/MoneyCalendar.tsx:83:9:h3">{monthLabel(month)}</h3>
        <button onClick={() => move(1)} aria-label="下个月" data-aime-component-name="button"  data-aime-path-name="src/components/life/MoneyCalendar.tsx"  data-aime-column="9"  data-aime-line="84"  data-insp-path="src/components/life/MoneyCalendar.tsx:84:9:button" >
          <ChevronRight size={17}  data-aime-component-name="ChevronRight"  data-aime-path-name="src/components/life/MoneyCalendar.tsx"  data-aime-column="11"  data-aime-line="85"  data-insp-path="src/components/life/MoneyCalendar.tsx:85:11:ChevronRight" />
        </button>
      </div>
      <div className="money-weekdays" data-aime-component-name="div"  data-aime-path-name="src/components/life/MoneyCalendar.tsx"  data-aime-column="7"  data-aime-line="88"  data-insp-path="src/components/life/MoneyCalendar.tsx:88:7:div" >
        {['日', '一', '二', '三', '四', '五', '六'].map(item => (
          <span key={item} data-aime-component-name="span"  data-aime-path-name="src/components/life/MoneyCalendar.tsx"  data-aime-column="11"  data-aime-line="90"  data-insp-path="src/components/life/MoneyCalendar.tsx:90:11:span" >{item}</span>
        ))}
      </div>
      <div className="money-calendar-grid" data-aime-component-name="div"  data-aime-path-name="src/components/life/MoneyCalendar.tsx"  data-aime-column="7"  data-aime-line="93"  data-insp-path="src/components/life/MoneyCalendar.tsx:93:7:div" >
        {cells.map(cell => {
          if (!cell.day)
            return <span className="money-day empty" key={cell.key}  data-aime-component-name="span"  data-aime-path-name="src/components/life/MoneyCalendar.tsx"  data-aime-column="20"  data-aime-line="96"  data-insp-path="src/components/life/MoneyCalendar.tsx:96:20:span" />;
          const iso = `${month}-${String(cell.day).padStart(2, '0')}`;
          const total = summarizeTransactions(byDay.get(iso) ?? []);
          return (
            <button
              className={`money-day ${selected === iso ? 'selected' : ''}`}
              key={iso}
              onClick={() => setSelected(iso)}
             data-aime-component-name="button"  data-aime-path-name="src/components/life/MoneyCalendar.tsx"  data-aime-column="13"  data-aime-line="100"  data-insp-path="src/components/life/MoneyCalendar.tsx:100:13:button" >
              <b data-aime-component-name="b" data-aime-path-name="src/components/life/MoneyCalendar.tsx" data-aime-column="15" data-aime-line="105" data-insp-path="src/components/life/MoneyCalendar.tsx:105:15:b">{cell.day}</b>
              <small className="day-income" data-aime-component-name="small"  data-aime-path-name="src/components/life/MoneyCalendar.tsx"  data-aime-column="15"  data-aime-line="106"  data-insp-path="src/components/life/MoneyCalendar.tsx:106:15:small" >
                {total.income ? `+${formatCents(total.income)}` : ''}
              </small>
              <small className="day-expense" data-aime-component-name="small"  data-aime-path-name="src/components/life/MoneyCalendar.tsx"  data-aime-column="15"  data-aime-line="109"  data-insp-path="src/components/life/MoneyCalendar.tsx:109:15:small" >
                {total.expense ? `-${formatCents(total.expense)}` : ''}
              </small>
            </button>
          );
        })}
      </div>
      <div className="day-transactions" data-aime-component-name="div"  data-aime-path-name="src/components/life/MoneyCalendar.tsx"  data-aime-column="7"  data-aime-line="116"  data-insp-path="src/components/life/MoneyCalendar.tsx:116:7:div" >
        <div className="selected-date" data-aime-component-name="div"  data-aime-path-name="src/components/life/MoneyCalendar.tsx"  data-aime-column="9"  data-aime-line="117"  data-insp-path="src/components/life/MoneyCalendar.tsx:117:9:div" >
          <b data-aime-component-name="b" data-aime-path-name="src/components/life/MoneyCalendar.tsx" data-aime-column="11" data-aime-line="118" data-insp-path="src/components/life/MoneyCalendar.tsx:118:11:b">{selected.slice(5).replace('-', ' / ')}</b>
          <span data-aime-component-name="span" data-aime-path-name="src/components/life/MoneyCalendar.tsx" data-aime-column="11" data-aime-line="119" data-insp-path="src/components/life/MoneyCalendar.tsx:119:11:span">{selectedItems.length} 笔</span>
        </div>
        {selectedItems.length ? (
          selectedItems.map(item => (
            <div className="transaction-row" key={item.id} data-aime-component-name="div"  data-aime-path-name="src/components/life/MoneyCalendar.tsx"  data-aime-column="13"  data-aime-line="123"  data-insp-path="src/components/life/MoneyCalendar.tsx:123:13:div" >
              <i className={item.kind}  data-aime-component-name="i"  data-aime-path-name="src/components/life/MoneyCalendar.tsx"  data-aime-column="15"  data-aime-line="124"  data-insp-path="src/components/life/MoneyCalendar.tsx:124:15:i" />
              <span data-aime-component-name="span" data-aime-path-name="src/components/life/MoneyCalendar.tsx" data-aime-column="15" data-aime-line="125" data-insp-path="src/components/life/MoneyCalendar.tsx:125:15:span">
                <b data-aime-component-name="b" data-aime-path-name="src/components/life/MoneyCalendar.tsx" data-aime-column="17" data-aime-line="126" data-insp-path="src/components/life/MoneyCalendar.tsx:126:17:b">{item.detail}</b>
                <small data-aime-component-name="small" data-aime-path-name="src/components/life/MoneyCalendar.tsx" data-aime-column="17" data-aime-line="127" data-insp-path="src/components/life/MoneyCalendar.tsx:127:17:small">{item.kind === 'income' ? '收入' : '支出'}</small>
              </span>
              <strong className={item.kind} data-aime-component-name="strong"  data-aime-path-name="src/components/life/MoneyCalendar.tsx"  data-aime-column="15"  data-aime-line="129"  data-insp-path="src/components/life/MoneyCalendar.tsx:129:15:strong" >
                {item.kind === 'income' ? '+' : '-'}¥
                {formatCents(item.amountCents)}
              </strong>
              <button
                onClick={() => setPendingRemoval(item.id)}
                aria-label={`删除${item.detail}`}
               data-aime-component-name="button"  data-aime-path-name="src/components/life/MoneyCalendar.tsx"  data-aime-column="15"  data-aime-line="133"  data-insp-path="src/components/life/MoneyCalendar.tsx:133:15:button" >
                <Trash2 size={14}  data-aime-component-name="Trash2"  data-aime-path-name="src/components/life/MoneyCalendar.tsx"  data-aime-column="17"  data-aime-line="137"  data-insp-path="src/components/life/MoneyCalendar.tsx:137:17:Trash2" />
              </button>
            </div>
          ))
        ) : (
          <p className="empty-money-day" data-aime-component-name="p"  data-aime-path-name="src/components/life/MoneyCalendar.tsx"  data-aime-column="11"  data-aime-line="142"  data-insp-path="src/components/life/MoneyCalendar.tsx:142:11:p" >这天还没有明细</p>
        )}
        <div className={`money-inline-entry ${kind}`} data-aime-component-name="div"  data-aime-path-name="src/components/life/MoneyCalendar.tsx"  data-aime-column="9"  data-aime-line="144"  data-insp-path="src/components/life/MoneyCalendar.tsx:144:9:div" >
          <fieldset className="money-kind" aria-label="收支类型" data-aime-component-name="fieldset"  data-aime-path-name="src/components/life/MoneyCalendar.tsx"  data-aime-column="11"  data-aime-line="145"  data-insp-path="src/components/life/MoneyCalendar.tsx:145:11:fieldset" >
            <button
              className={kind === 'expense' ? 'active' : ''}
              onClick={() => setKind('expense')}
             data-aime-component-name="button"  data-aime-path-name="src/components/life/MoneyCalendar.tsx"  data-aime-column="13"  data-aime-line="146"  data-insp-path="src/components/life/MoneyCalendar.tsx:146:13:button" >
              支出
            </button>
            <button
              className={kind === 'income' ? 'active' : ''}
              onClick={() => setKind('income')}
             data-aime-component-name="button"  data-aime-path-name="src/components/life/MoneyCalendar.tsx"  data-aime-column="13"  data-aime-line="152"  data-insp-path="src/components/life/MoneyCalendar.tsx:152:13:button" >
              收入
            </button>
          </fieldset>
          <div className="money-inline-fields" data-aime-component-name="div"  data-aime-path-name="src/components/life/MoneyCalendar.tsx"  data-aime-column="11"  data-aime-line="159"  data-insp-path="src/components/life/MoneyCalendar.tsx:159:11:div" >
            <label data-aime-component-name="label" data-aime-path-name="src/components/life/MoneyCalendar.tsx" data-aime-column="13" data-aime-line="160" data-insp-path="src/components/life/MoneyCalendar.tsx:160:13:label">
              <span data-aime-component-name="span" data-aime-path-name="src/components/life/MoneyCalendar.tsx" data-aime-column="15" data-aime-line="161" data-insp-path="src/components/life/MoneyCalendar.tsx:161:15:span">¥</span>
              <input
                aria-label="金额"
                inputMode="decimal"
                value={amount}
                onChange={event =>
                  setAmount(event.target.value.replace(/[^\d.]/g, ''))
                }
                placeholder="0.00"
               data-aime-component-name="input"  data-aime-path-name="src/components/life/MoneyCalendar.tsx"  data-aime-column="15"  data-aime-line="162"  data-insp-path="src/components/life/MoneyCalendar.tsx:162:15:input" />
            </label>
            <input
              aria-label="明细"
              value={detail}
              onChange={event => setDetail(event.target.value)}
              onKeyDown={event => event.key === 'Enter' && submit()}
              placeholder="明细"
             data-aime-component-name="input"  data-aime-path-name="src/components/life/MoneyCalendar.tsx"  data-aime-column="13"  data-aime-line="172"  data-insp-path="src/components/life/MoneyCalendar.tsx:172:13:input" />
            <button onClick={submit} aria-label="添加到选中日期" data-aime-component-name="button"  data-aime-path-name="src/components/life/MoneyCalendar.tsx"  data-aime-column="13"  data-aime-line="179"  data-insp-path="src/components/life/MoneyCalendar.tsx:179:13:button" >
              <Check size={16}  data-aime-component-name="Check"  data-aime-path-name="src/components/life/MoneyCalendar.tsx"  data-aime-column="15"  data-aime-line="180"  data-insp-path="src/components/life/MoneyCalendar.tsx:180:15:Check" />
            </button>
          </div>
          <small data-aime-component-name="small" data-aime-path-name="src/components/life/MoneyCalendar.tsx" data-aime-column="11" data-aime-line="183" data-insp-path="src/components/life/MoneyCalendar.tsx:183:11:small">新增记录将保存到 {selected}</small>
        </div>
      </div>
      <ConfirmModal
        open={pendingRemoval !== null}
        title="删除记账明细"
        message="删除后无法恢复，确定移除这条收支明细吗？"
        confirmLabel="删除"
        onCancel={() => setPendingRemoval(null)}
        onConfirm={remove}
       data-aime-component-name="ConfirmModal"  data-aime-path-name="src/components/life/MoneyCalendar.tsx"  data-aime-column="7"  data-aime-line="186"  data-insp-path="src/components/life/MoneyCalendar.tsx:186:7:ConfirmModal" />
    </section>
  );
}
