import type { MonthlyMoney } from '@/hooks/useLifeStore';
import { upsertMonthlyMoney } from '@/lib/lifeRules';
import { Pencil, X } from 'lucide-react';
import { useEffect, useState } from 'react';
import { createPortal } from 'react-dom';

interface Props {
  items: MonthlyMoney[];
  onChange: (items: MonthlyMoney[]) => void;
  notify: (text: string) => void;
}

const currentMonth = () => {
  const today = new Date();
  return `${today.getFullYear()}-${String(today.getMonth() + 1).padStart(2, '0')}`;
};
const validAmount = (value: string) =>
  value === '' || /^(?:0|[1-9]\d*)(?:\.\d{0,2})?$/.test(value);

export function MonthlyMoneyEditor({ items, onChange, notify }: Props) {
  const [open, setOpen] = useState(false);
  const [month, setMonth] = useState(currentMonth);
  const [income, setIncome] = useState('');
  const [expense, setExpense] = useState('');

  useEffect(() => {
    const saved = items.find(item => item.month === month);
    setIncome(saved ? String(saved.income) : '');
    setExpense(saved ? String(saved.expense) : '');
  }, [items, month]);

  useEffect(() => {
    if (!open) return;
    const closeOnEscape = (event: KeyboardEvent) => {
      if (event.key === 'Escape') setOpen(false);
    };
    window.addEventListener('keydown', closeOnEscape);
    return () => window.removeEventListener('keydown', closeOnEscape);
  }, [open]);

  const save = () => {
    if (!/^\d{4}-\d{2}$/.test(month) || month > currentMonth()) {
      notify('请选择当前或更早的月份');
      return;
    }
    if (!validAmount(income) || !validAmount(expense)) {
      notify('金额需为非负数，最多保留两位小数');
      return;
    }
    onChange(
      upsertMonthlyMoney(items, {
        month,
        income: Number(income || 0),
        expense: Number(expense || 0),
      }),
    );
    setOpen(false);
    notify('月度收支已保存');
  };

  return (
    <>
      <button
        type="button"
        className="monthly-edit-button"
        onClick={() => setOpen(true)}
        aria-label="编辑历史月度收支"
       data-aime-component-name="button"  data-aime-path-name="src/components/life/MonthlyMoneyEditor.tsx"  data-aime-column="7"  data-aime-line="63"  data-insp-path="src/components/life/MonthlyMoneyEditor.tsx:63:7:button" >
        <Pencil size={12}  data-aime-component-name="Pencil"  data-aime-path-name="src/components/life/MonthlyMoneyEditor.tsx"  data-aime-column="9"  data-aime-line="69"  data-insp-path="src/components/life/MonthlyMoneyEditor.tsx:69:9:Pencil" />
        编辑历史
      </button>
      {open &&
        typeof document !== 'undefined' &&
        createPortal(
          <div
            className="monthly-money-mask"
            role="presentation"
            onPointerDown={() => setOpen(false)}
           data-aime-component-name="div"  data-aime-path-name="src/components/life/MonthlyMoneyEditor.tsx"  data-aime-column="11"  data-aime-line="75"  data-insp-path="src/components/life/MonthlyMoneyEditor.tsx:75:11:div" >
            <dialog
              open
              className="monthly-money-dialog"
              aria-labelledby="monthly-money-title"
              onPointerDown={event => event.stopPropagation()}
             data-aime-component-name="dialog"  data-aime-path-name="src/components/life/MonthlyMoneyEditor.tsx"  data-aime-column="13"  data-aime-line="80"  data-insp-path="src/components/life/MonthlyMoneyEditor.tsx:80:13:dialog" >
              <div className="monthly-money-head" data-aime-component-name="div"  data-aime-path-name="src/components/life/MonthlyMoneyEditor.tsx"  data-aime-column="15"  data-aime-line="86"  data-insp-path="src/components/life/MonthlyMoneyEditor.tsx:86:15:div" >
                <div data-aime-component-name="div" data-aime-path-name="src/components/life/MonthlyMoneyEditor.tsx" data-aime-column="17" data-aime-line="87" data-insp-path="src/components/life/MonthlyMoneyEditor.tsx:87:17:div">
                  <span data-aime-component-name="span" data-aime-path-name="src/components/life/MonthlyMoneyEditor.tsx" data-aime-column="19" data-aime-line="88" data-insp-path="src/components/life/MonthlyMoneyEditor.tsx:88:19:span">MONTHLY RECORD</span>
                  <h2 id="monthly-money-title" data-aime-component-name="h2"  data-aime-path-name="src/components/life/MonthlyMoneyEditor.tsx"  data-aime-column="19"  data-aime-line="89"  data-insp-path="src/components/life/MonthlyMoneyEditor.tsx:89:19:h2" >编辑历史月度收支</h2>
                </div>
                <button
                  type="button"
                  onClick={() => setOpen(false)}
                  aria-label="关闭"
                 data-aime-component-name="button"  data-aime-path-name="src/components/life/MonthlyMoneyEditor.tsx"  data-aime-column="17"  data-aime-line="91"  data-insp-path="src/components/life/MonthlyMoneyEditor.tsx:91:17:button" >
                  <X size={17}  data-aime-component-name="X"  data-aime-path-name="src/components/life/MonthlyMoneyEditor.tsx"  data-aime-column="19"  data-aime-line="96"  data-insp-path="src/components/life/MonthlyMoneyEditor.tsx:96:19:X" />
                </button>
              </div>
              <p className="monthly-money-tip" data-aime-component-name="p"  data-aime-path-name="src/components/life/MonthlyMoneyEditor.tsx"  data-aime-column="15"  data-aime-line="99"  data-insp-path="src/components/life/MonthlyMoneyEditor.tsx:99:15:p" >
                仅在该月没有任何日明细时用于图表；清空金额会按 0 元保存。
              </p>
              <label data-aime-component-name="label" data-aime-path-name="src/components/life/MonthlyMoneyEditor.tsx" data-aime-column="15" data-aime-line="102" data-insp-path="src/components/life/MonthlyMoneyEditor.tsx:102:15:label">
                月份
                <input
                  type="month"
                  max={currentMonth()}
                  value={month}
                  onChange={event => setMonth(event.target.value)}
                 data-aime-component-name="input"  data-aime-path-name="src/components/life/MonthlyMoneyEditor.tsx"  data-aime-column="17"  data-aime-line="104"  data-insp-path="src/components/life/MonthlyMoneyEditor.tsx:104:17:input" />
              </label>
              <div className="monthly-money-fields" data-aime-component-name="div"  data-aime-path-name="src/components/life/MonthlyMoneyEditor.tsx"  data-aime-column="15"  data-aime-line="111"  data-insp-path="src/components/life/MonthlyMoneyEditor.tsx:111:15:div" >
                <label data-aime-component-name="label" data-aime-path-name="src/components/life/MonthlyMoneyEditor.tsx" data-aime-column="17" data-aime-line="112" data-insp-path="src/components/life/MonthlyMoneyEditor.tsx:112:17:label">
                  总收入（元）
                  <input
                    type="text"
                    inputMode="decimal"
                    value={income}
                    placeholder="0.00"
                    onChange={event => setIncome(event.target.value.trim())}
                   data-aime-component-name="input"  data-aime-path-name="src/components/life/MonthlyMoneyEditor.tsx"  data-aime-column="19"  data-aime-line="114"  data-insp-path="src/components/life/MonthlyMoneyEditor.tsx:114:19:input" />
                </label>
                <label data-aime-component-name="label" data-aime-path-name="src/components/life/MonthlyMoneyEditor.tsx" data-aime-column="17" data-aime-line="122" data-insp-path="src/components/life/MonthlyMoneyEditor.tsx:122:17:label">
                  总支出（元）
                  <input
                    type="text"
                    inputMode="decimal"
                    value={expense}
                    placeholder="0.00"
                    onChange={event => setExpense(event.target.value.trim())}
                   data-aime-component-name="input"  data-aime-path-name="src/components/life/MonthlyMoneyEditor.tsx"  data-aime-column="19"  data-aime-line="124"  data-insp-path="src/components/life/MonthlyMoneyEditor.tsx:124:19:input" />
                </label>
              </div>
              <div className="monthly-money-actions" data-aime-component-name="div"  data-aime-path-name="src/components/life/MonthlyMoneyEditor.tsx"  data-aime-column="15"  data-aime-line="133"  data-insp-path="src/components/life/MonthlyMoneyEditor.tsx:133:15:div" >
                <button type="button" onClick={() => setOpen(false)} data-aime-component-name="button"  data-aime-path-name="src/components/life/MonthlyMoneyEditor.tsx"  data-aime-column="17"  data-aime-line="134"  data-insp-path="src/components/life/MonthlyMoneyEditor.tsx:134:17:button" >
                  取消
                </button>
                <button type="button" onClick={save} data-aime-component-name="button"  data-aime-path-name="src/components/life/MonthlyMoneyEditor.tsx"  data-aime-column="17"  data-aime-line="137"  data-insp-path="src/components/life/MonthlyMoneyEditor.tsx:137:17:button" >
                  保存记录
                </button>
              </div>
            </dialog>
          </div>,
          document.body,
        )}
    </>
  );
}
