import { compressImage } from '@/lib/lifeUtils';
import { Eraser, ImagePlus, RotateCcw, Save, Trash2 } from 'lucide-react';
import { useEffect, useRef, useState } from 'react';
interface Props {
  onSave: (image: string) => void;
  notify: (text: string) => void;
}
export function DrawingEditor({ onSave, notify }: Props) {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const history = useRef<string[]>([]);
  const drawing = useRef(false);
  const [color, setColor] = useState('#546d73');
  const [width, setWidth] = useState(4);
  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;
    ctx.fillStyle = '#fffaf1';
    ctx.fillRect(0, 0, canvas.width, canvas.height);
    history.current = [canvas.toDataURL()];
  }, []);
  const point = (event: React.PointerEvent<HTMLCanvasElement>) => {
    const rect = event.currentTarget.getBoundingClientRect();
    return {
      x: (event.clientX - rect.left) * (event.currentTarget.width / rect.width),
      y:
        (event.clientY - rect.top) * (event.currentTarget.height / rect.height),
    };
  };
  const start = (event: React.PointerEvent<HTMLCanvasElement>) => {
    drawing.current = true;
    event.currentTarget.setPointerCapture(event.pointerId);
    const p = point(event);
    const ctx = event.currentTarget.getContext('2d');
    if (ctx) {
      ctx.beginPath();
      ctx.moveTo(p.x, p.y);
      ctx.strokeStyle = color;
      ctx.lineWidth = width;
      ctx.lineCap = 'round';
      ctx.lineJoin = 'round';
    }
  };
  const move = (event: React.PointerEvent<HTMLCanvasElement>) => {
    if (!drawing.current) return;
    const p = point(event);
    const ctx = event.currentTarget.getContext('2d');
    if (ctx) {
      ctx.lineTo(p.x, p.y);
      ctx.stroke();
    }
  };
  const end = () => {
    if (!drawing.current) return;
    drawing.current = false;
    const image = canvasRef.current?.toDataURL();
    if (image) history.current.push(image);
  };
  const restore = (image: string) => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    const img = new Image();
    img.onload = () => ctx?.drawImage(img, 0, 0, canvas.width, canvas.height);
    img.src = image;
  };
  const clear = () => {
    const canvas = canvasRef.current;
    const ctx = canvas?.getContext('2d');
    if (!canvas || !ctx) return;
    ctx.fillStyle = '#fffaf1';
    ctx.fillRect(0, 0, canvas.width, canvas.height);
    history.current.push(canvas.toDataURL());
  };
  return (
    <div className="drawing-editor" data-aime-component-name="div"  data-aime-path-name="src/components/life/DrawingEditor.tsx"  data-aime-column="5"  data-aime-line="77"  data-insp-path="src/components/life/DrawingEditor.tsx:77:5:div" >
      <div className="draw-tools" data-aime-component-name="div"  data-aime-path-name="src/components/life/DrawingEditor.tsx"  data-aime-column="7"  data-aime-line="78"  data-insp-path="src/components/life/DrawingEditor.tsx:78:7:div" >
        <div data-aime-component-name="div" data-aime-path-name="src/components/life/DrawingEditor.tsx" data-aime-column="9" data-aime-line="79" data-insp-path="src/components/life/DrawingEditor.tsx:79:9:div">
          {['#546d73', '#c47f78', '#c39c43'].map(c => (
            <button
              key={c}
              className={color === c ? 'active' : ''}
              style={{ background: c }}
              onClick={() => setColor(c)}
              aria-label="选择笔色"
             data-aime-component-name="button"  data-aime-path-name="src/components/life/DrawingEditor.tsx"  data-aime-column="13"  data-aime-line="81"  data-insp-path="src/components/life/DrawingEditor.tsx:81:13:button" />
          ))}
        </div>
        <label data-aime-component-name="label" data-aime-path-name="src/components/life/DrawingEditor.tsx" data-aime-column="9" data-aime-line="90" data-insp-path="src/components/life/DrawingEditor.tsx:90:9:label">
          笔粗{' '}
          <input
            type="range"
            min="2"
            max="14"
            value={width}
            onChange={e => setWidth(Number(e.target.value))}
           data-aime-component-name="input"  data-aime-path-name="src/components/life/DrawingEditor.tsx"  data-aime-column="11"  data-aime-line="92"  data-insp-path="src/components/life/DrawingEditor.tsx:92:11:input" />
        </label>
      </div>
      <canvas
        ref={canvasRef}
        width={600}
        height={760}
        onPointerDown={start}
        onPointerMove={move}
        onPointerUp={end}
        onPointerCancel={end}
       data-aime-component-name="canvas"  data-aime-path-name="src/components/life/DrawingEditor.tsx"  data-aime-column="7"  data-aime-line="101"  data-insp-path="src/components/life/DrawingEditor.tsx:101:7:canvas" />
      <div className="draw-actions" data-aime-component-name="div"  data-aime-path-name="src/components/life/DrawingEditor.tsx"  data-aime-column="7"  data-aime-line="110"  data-insp-path="src/components/life/DrawingEditor.tsx:110:7:div" >
        <button
          onClick={() => {
            if (history.current.length > 1) {
              history.current.pop();
              restore(history.current.at(-1) as string);
            }
          }}
         data-aime-component-name="button"  data-aime-path-name="src/components/life/DrawingEditor.tsx"  data-aime-column="9"  data-aime-line="111"  data-insp-path="src/components/life/DrawingEditor.tsx:111:9:button" >
          <RotateCcw  data-aime-component-name="RotateCcw" data-aime-path-name="src/components/life/DrawingEditor.tsx" data-aime-column="11" data-aime-line="119" data-insp-path="src/components/life/DrawingEditor.tsx:119:11:RotateCcw"/>
          撤销
        </button>
        <button onClick={clear} data-aime-component-name="button"  data-aime-path-name="src/components/life/DrawingEditor.tsx"  data-aime-column="9"  data-aime-line="122"  data-insp-path="src/components/life/DrawingEditor.tsx:122:9:button" >
          <Trash2  data-aime-component-name="Trash2" data-aime-path-name="src/components/life/DrawingEditor.tsx" data-aime-column="11" data-aime-line="123" data-insp-path="src/components/life/DrawingEditor.tsx:123:11:Trash2"/>
          清空
        </button>
        <label data-aime-component-name="label" data-aime-path-name="src/components/life/DrawingEditor.tsx" data-aime-column="9" data-aime-line="126" data-insp-path="src/components/life/DrawingEditor.tsx:126:9:label">
          <ImagePlus  data-aime-component-name="ImagePlus" data-aime-path-name="src/components/life/DrawingEditor.tsx" data-aime-column="11" data-aime-line="127" data-insp-path="src/components/life/DrawingEditor.tsx:127:11:ImagePlus"/>
          从其他 App 导入
          <input
            hidden
            type="file"
            accept="image/*"
            onChange={async e => {
              const file = e.target.files?.[0];
              if (!file) return;
              try {
                const image = await compressImage(file, 900, 0.75);
                restore(image);
                history.current.push(image);
              } catch (err) {
                notify((err as Error).message);
              }
            }}
           data-aime-component-name="input"  data-aime-path-name="src/components/life/DrawingEditor.tsx"  data-aime-column="11"  data-aime-line="129"  data-insp-path="src/components/life/DrawingEditor.tsx:129:11:input" />
        </label>
        <button
          className="save-drawing"
          onClick={() => {
            const image = canvasRef.current?.toDataURL('image/jpeg', 0.72);
            if (image) onSave(image);
          }}
         data-aime-component-name="button"  data-aime-path-name="src/components/life/DrawingEditor.tsx"  data-aime-column="9"  data-aime-line="146"  data-insp-path="src/components/life/DrawingEditor.tsx:146:9:button" >
          <Save  data-aime-component-name="Save" data-aime-path-name="src/components/life/DrawingEditor.tsx" data-aime-column="11" data-aime-line="153" data-insp-path="src/components/life/DrawingEditor.tsx:153:11:Save"/>
          保存为卡面
        </button>
      </div>
      <p data-aime-component-name="p" data-aime-path-name="src/components/life/DrawingEditor.tsx" data-aime-column="7" data-aime-line="157" data-insp-path="src/components/life/DrawingEditor.tsx:157:7:p">
        <Eraser size={12}  data-aime-component-name="Eraser"  data-aime-path-name="src/components/life/DrawingEditor.tsx"  data-aime-column="9"  data-aime-line="158"  data-insp-path="src/components/life/DrawingEditor.tsx:158:9:Eraser" />
        可以先在美图、Procreate 或系统相册完成，再从这里导入。
      </p>
    </div>
  );
}
