import type { PendingExpense } from '@/hooks/useLifeStore';
import { formatCents, parseMoneyToCents } from '@/lib/lifeRules';
import { Plus, Trash2 } from 'lucide-react';
import { useState } from 'react';
import { ConfirmModal } from './ConfirmModal';

interface Props {
  items: PendingExpense[];
  onChange: (items: PendingExpense[]) => void;
  notify: (text: string) => void;
}

export function PendingExpenses({ items, onChange, notify }: Props) {
  const [name, setName] = useState('');
  const [amount, setAmount] = useState('');
  const [pendingRemoval, setPendingRemoval] = useState<number | null>(null);
  const add = () => {
    try {
      if (!name.trim()) throw new Error('请填写待支出名称');
      onChange([
        ...items,
        {
          id: Date.now(),
          name: name.trim(),
          amountCents: parseMoneyToCents(amount),
        },
      ]);
      setName('');
      setAmount('');
    } catch (error) {
      notify((error as Error).message);
    }
  };
  const remove = () => {
    if (pendingRemoval === null) return;
    onChange(items.filter(item => item.id !== pendingRemoval));
    setPendingRemoval(null);
  };
  return (
    <section className="pending-expenses" data-aime-component-name="section"  data-aime-path-name="src/components/life/PendingExpenses.tsx"  data-aime-column="5"  data-aime-line="40"  data-insp-path="src/components/life/PendingExpenses.tsx:40:5:section" >
      <div className="section-heading" data-aime-component-name="div"  data-aime-path-name="src/components/life/PendingExpenses.tsx"  data-aime-column="7"  data-aime-line="41"  data-insp-path="src/components/life/PendingExpenses.tsx:41:7:div" >
        <div data-aime-component-name="div" data-aime-path-name="src/components/life/PendingExpenses.tsx" data-aime-column="9" data-aime-line="42" data-insp-path="src/components/life/PendingExpenses.tsx:42:9:div">
          <span className="overline" data-aime-component-name="span"  data-aime-path-name="src/components/life/PendingExpenses.tsx"  data-aime-column="11"  data-aime-line="43"  data-insp-path="src/components/life/PendingExpenses.tsx:43:11:span" >UPCOMING</span>
          <h2 data-aime-component-name="h2" data-aime-path-name="src/components/life/PendingExpenses.tsx" data-aime-column="11" data-aime-line="44" data-insp-path="src/components/life/PendingExpenses.tsx:44:11:h2">待支出</h2>
        </div>
      </div>
      <div className="pending-compose" data-aime-component-name="div"  data-aime-path-name="src/components/life/PendingExpenses.tsx"  data-aime-column="7"  data-aime-line="47"  data-insp-path="src/components/life/PendingExpenses.tsx:47:7:div" >
        <input
          value={name}
          onChange={event => setName(event.target.value)}
          placeholder="名称"
         data-aime-component-name="input"  data-aime-path-name="src/components/life/PendingExpenses.tsx"  data-aime-column="9"  data-aime-line="48"  data-insp-path="src/components/life/PendingExpenses.tsx:48:9:input" />
        <input
          inputMode="decimal"
          value={amount}
          onChange={event =>
            setAmount(event.target.value.replace(/[^\d.]/g, ''))
          }
          placeholder="预计金额"
         data-aime-component-name="input"  data-aime-path-name="src/components/life/PendingExpenses.tsx"  data-aime-column="9"  data-aime-line="53"  data-insp-path="src/components/life/PendingExpenses.tsx:53:9:input" />
        <button onClick={add} aria-label="添加待支出" data-aime-component-name="button"  data-aime-path-name="src/components/life/PendingExpenses.tsx"  data-aime-column="9"  data-aime-line="61"  data-insp-path="src/components/life/PendingExpenses.tsx:61:9:button" >
          <Plus size={15}  data-aime-component-name="Plus"  data-aime-path-name="src/components/life/PendingExpenses.tsx"  data-aime-column="11"  data-aime-line="62"  data-insp-path="src/components/life/PendingExpenses.tsx:62:11:Plus" />
        </button>
      </div>
      <div className="pending-list" data-aime-component-name="div"  data-aime-path-name="src/components/life/PendingExpenses.tsx"  data-aime-column="7"  data-aime-line="65"  data-insp-path="src/components/life/PendingExpenses.tsx:65:7:div" >
        {items.map(item => (
          <div key={item.id} data-aime-component-name="div"  data-aime-path-name="src/components/life/PendingExpenses.tsx"  data-aime-column="11"  data-aime-line="67"  data-insp-path="src/components/life/PendingExpenses.tsx:67:11:div" >
            <span data-aime-component-name="span" data-aime-path-name="src/components/life/PendingExpenses.tsx" data-aime-column="13" data-aime-line="68" data-insp-path="src/components/life/PendingExpenses.tsx:68:13:span">{item.name}</span>
            <b data-aime-component-name="b" data-aime-path-name="src/components/life/PendingExpenses.tsx" data-aime-column="13" data-aime-line="69" data-insp-path="src/components/life/PendingExpenses.tsx:69:13:b">¥{formatCents(item.amountCents)}</b>
            <button
              onClick={() => setPendingRemoval(item.id)}
              aria-label={`删除${item.name}`}
             data-aime-component-name="button"  data-aime-path-name="src/components/life/PendingExpenses.tsx"  data-aime-column="13"  data-aime-line="70"  data-insp-path="src/components/life/PendingExpenses.tsx:70:13:button" >
              <Trash2 size={13}  data-aime-component-name="Trash2"  data-aime-path-name="src/components/life/PendingExpenses.tsx"  data-aime-column="15"  data-aime-line="74"  data-insp-path="src/components/life/PendingExpenses.tsx:74:15:Trash2" />
            </button>
          </div>
        ))}
      </div>
      <ConfirmModal
        open={pendingRemoval !== null}
        title="删除待支出"
        message="确定删除这项待支出吗？"
        confirmLabel="删除"
        onCancel={() => setPendingRemoval(null)}
        onConfirm={remove}
       data-aime-component-name="ConfirmModal"  data-aime-path-name="src/components/life/PendingExpenses.tsx"  data-aime-column="7"  data-aime-line="79"  data-insp-path="src/components/life/PendingExpenses.tsx:79:7:ConfirmModal" />
    </section>
  );
}
