          <Plus size={14}  data-aime-component-name="Plus"  data-aime-path-name="src/components/life/ItemConfigPanel.tsx"  data-aime-column="11"  data-aime-line="80"  data-insp-path="src/components/life/ItemConfigPanel.tsx:80:11:Plus" />
